		public void SendEntryPlayerDataToAll(int userEntryNumber, float wazaSeqMaxTime, global::Dpr.BallDeco.AffixSealData[] sealDataArray) {
			if (entryPlayerData == null)
			{
				entryPlayerData = new ContestEntryPlayerNetData();
				entryPlayerData.data.sealDataArray = new SealParam[20];
			}

			EntryPlayerData entry = ContestWork.entryPlayerDatas[userEntryNumber];
			ContestEntryPlayerData data = entryPlayerData.data;
			data.playerSex = (byte)entry.playerSex;
			data.userLangId = (byte)Dpr.Message.MessageManager.Instance.UserLanguageID;
			data.fasion = entry.fashion;
			data.colorID = (byte)entry.colorID;
			data.pokeNickName = Dpr.SubContents.Utils.CheckNGPokeName(ref entry.pokemonNickName, entry.monsNo, entry.monsLangID);
			data.monsNo = (ushort)entry.monsNo;
			data.monsFormNo = (byte)entry.formNo;
			data.monsSex = (byte)entry.monsSex;
			data.isRare = entry.isRare;
			data.rareType = (byte)entry.rareType;
			data.style = entry.style;
			data.beautiful = entry.beautiful;
			data.cute = entry.cute;
			data.clever = entry.clever;
			data.strong = entry.strong;
			data.fur = entry.fur;
			data.monsLangId = (byte)entry.monsLangID;
			data.wazaNo = (ushort)entry.wazaNo;
			data.wazaSeqTime = wazaSeqMaxTime;
			data.itemNo = entry.itemNo;
			data.ballID = (byte)entry.ballInfo.ballId;
			entry.ballInfo.affixSealDatas = sealDataArray;
			entry.ballInfo.sealCnt = 0;
			for (int i = 0; i < sealDataArray.Length; i++)
			{
				AffixSealData affixSealData = sealDataArray[i];
				SealParam sealParam = data.sealDataArray[i];
				if (affixSealData.SealId != 0)
					entry.ballInfo.sealCnt++;

				sealParam.sealID = (byte)affixSealData.SealId;
				sealParam.sealPosX = affixSealData.PositionX;
				sealParam.sealPosY = affixSealData.PositionY;
				sealParam.sealPosZ = affixSealData.PositionZ;
				data.sealDataArray[i] = sealParam;
			}
			entryPlayerData.data = data;
			SendDataToAll(entryPlayerData);
		}
